//! Nonblocking producer queue with independent payload-byte and item limits.
//! On overload callers MUST report an incomplete recording, never hide a drop.
//! Accepted items remain drainable after all senders close.
use std::sync::{Arc, atomic::{AtomicUsize, Ordering}};
use tokio::sync::{mpsc, oneshot};

pub trait QueuePayload { fn heap_bytes(&self) -> usize; }
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QueueError { Full, Closed }
impl std::fmt::Display for QueueError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", match self { Self::Full => "audio queue capacity exceeded", Self::Closed => "audio queue closed" })
    }
}
impl std::error::Error for QueueError {}
struct Reservation { bytes: usize, used: Arc<AtomicUsize> }
impl Drop for Reservation {
    fn drop(&mut self) { self.used.fetch_sub(self.bytes, Ordering::AcqRel); }
}
struct Envelope<T> { value: T, reservation: Reservation }
pub struct MemorySender<T> { sender: mpsc::Sender<Envelope<T>>, used: Arc<AtomicUsize>, limit: usize }
pub struct MemoryReceiver<T> { receiver: mpsc::Receiver<Envelope<T>> }
impl<T> Clone for MemorySender<T> {
    fn clone(&self) -> Self { Self { sender: self.sender.clone(), used: self.used.clone(), limit: self.limit } }
}
pub fn channel<T>(byte_limit: usize, item_limit: usize) -> (MemorySender<T>, MemoryReceiver<T>) {
    let (sender, receiver) = mpsc::channel(item_limit.max(1));
    (MemorySender { sender, used: Arc::new(AtomicUsize::new(0)), limit: byte_limit }, MemoryReceiver { receiver })
}
impl<T: QueuePayload> MemorySender<T> {
    /// Never waits for the consumer, storage or capacity (safe for capture paths).
    pub fn send(&self, value: T) -> Result<(), QueueError> {
        if self.sender.is_closed() { return Err(QueueError::Closed); }
        let bytes = value.heap_bytes().checked_add(std::mem::size_of::<Envelope<T>>()).ok_or(QueueError::Full)?;
        self.used.fetch_update(Ordering::AcqRel, Ordering::Acquire, |used| {
            used.checked_add(bytes).filter(|total| *total <= self.limit)
        }).map_err(|_| QueueError::Full)?;
        let envelope = Envelope { value, reservation: Reservation { bytes, used: self.used.clone() } };
        self.sender.try_send(envelope).map_err(|error| match error {
            mpsc::error::TrySendError::Full(_) => QueueError::Full,
            mpsc::error::TrySendError::Closed(_) => QueueError::Closed,
        })
    }
    pub fn pending_bytes(&self) -> usize { self.used.load(Ordering::Acquire) }
}
impl<T> MemoryReceiver<T> {
    fn unpack(envelope: Envelope<T>) -> T {
        let Envelope { value, reservation } = envelope;
        drop(reservation);
        value
    }
    pub async fn recv(&mut self) -> Option<T> { self.receiver.recv().await.map(Self::unpack) }
    pub fn blocking_recv(&mut self) -> Option<T> { self.receiver.blocking_recv().map(Self::unpack) }
}

/// Long-running encoding belongs on a dedicated thread, not an async executor.
/// Completion is observable: stop awaits this receipt rather than sleeping and
/// hoping accepted audio has been written.
pub fn spawn_drain_worker<T: Send + 'static>(
    mut receiver: MemoryReceiver<T>,
    mut consume: impl FnMut(T) -> Result<(), String> + Send + 'static,
) -> std::io::Result<oneshot::Receiver<Result<(), String>>> {
    let (sender, done) = oneshot::channel();
    std::thread::Builder::new().name("clawscribe-audio-writer".into()).spawn(move || {
        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            while let Some(value) = receiver.blocking_recv() { consume(value)?; }
            Ok(())
        })).unwrap_or_else(|_| Err("Audio checkpoint worker panicked; recovery files have been retained".into()));
        let _ = sender.send(result);
    })?;
    Ok(done)
}

#[cfg(test)]
mod tests {
    use super::*;
    impl QueuePayload for Vec<u8> { fn heap_bytes(&self) -> usize { self.capacity() } }
    #[tokio::test]
    async fn limits_allocated_capacity_not_only_length() {
        let (sender, mut receiver) = channel(512, 10);
        let mut small = Vec::with_capacity(200); small.push(1);
        sender.send(small).unwrap();
        assert!(sender.pending_bytes() >= 200);
        assert_eq!(sender.send(Vec::with_capacity(400)), Err(QueueError::Full));
        assert_eq!(receiver.recv().await.unwrap(), vec![1]);
        assert_eq!(sender.pending_bytes(), 0);
        sender.send(Vec::with_capacity(400)).unwrap();
    }
    #[tokio::test]
    async fn item_limit_releases_failed_reservation() {
        let (sender, mut receiver) = channel(4096, 1);
        sender.send(vec![1]).unwrap();
        let pending = sender.pending_bytes();
        assert_eq!(sender.send(vec![2]), Err(QueueError::Full));
        assert_eq!(sender.pending_bytes(), pending);
        receiver.recv().await.unwrap();
        assert_eq!(sender.pending_bytes(), 0);
    }
    #[test]
    fn receiver_drop_releases_queued_memory() {
        let (sender, receiver) = channel(4096, 10);
        sender.send(vec![1; 100]).unwrap();
        drop(receiver);
        assert_eq!(sender.pending_bytes(), 0);
        assert_eq!(sender.send(vec![2]), Err(QueueError::Closed));
    }
    #[tokio::test]
    async fn slow_writer_drains_every_accepted_item_before_completion() {
        let (sender, receiver) = channel(16384, 100);
        let collected = Arc::new(std::sync::Mutex::new(Vec::new()));
        let result = collected.clone();
        let done = spawn_drain_worker(receiver, move |item: Vec<u8>| {
            std::thread::sleep(std::time::Duration::from_millis(1));
            result.lock().unwrap().push(item[0]); Ok(())
        }).unwrap();
        for i in 0..100u8 { sender.send(vec![i]).unwrap(); }
        drop(sender);
        done.await.unwrap().unwrap();
        assert_eq!(*collected.lock().unwrap(), (0..100u8).collect::<Vec<_>>());
    }
    #[tokio::test]
    async fn failed_writer_cannot_report_success_or_accept_more_audio() {
        let (sender, receiver) = channel(4096, 10);
        let done = spawn_drain_worker(receiver, |_item: Vec<u8>| Err("Disk full".to_string())).unwrap();
        sender.send(vec![1]).unwrap();
        assert_eq!(done.await.unwrap(), Err("Disk full".to_string()));
        assert_eq!(sender.send(vec![2]), Err(QueueError::Closed));
    }
    #[test]
    fn concurrent_producers_cannot_exceed_the_byte_budget() {
        let (sender, _receiver) = channel(8192, 1000);
        std::thread::scope(|scope| {
            for _ in 0..8 { let sender = sender.clone(); scope.spawn(move || {
                for _ in 0..100 { let _ = sender.send(vec![0; 100]); assert!(sender.pending_bytes() <= 8192); }
            }); }
        });
        assert!(sender.pending_bytes() <= 8192);
    }
}

//! Bounded synchronous child-process I/O, for dedicated/blocking workers only.
//! Drains diagnostics while feeding input, enforces a deadline, and reaps on error.
use std::io::{Read, Write};
use std::process::{Command, ExitStatus, Stdio};
use std::time::{Duration, Instant};

pub struct ProcessOutput { pub status: ExitStatus, pub stderr: Vec<u8> }
const MAX_DIAGNOSTIC_BYTES: usize = 64 * 1024;

pub fn run(command: &mut Command, input: Option<&[u8]>, deadline: Duration) -> std::io::Result<ProcessOutput> {
    command.stdin(if input.is_some() { Stdio::piped() } else { Stdio::null() })
        .stdout(Stdio::null()).stderr(Stdio::piped());
    let mut child = command.spawn()?;
    let stdin = child.stdin.take();
    let mut stderr = child.stderr.take().ok_or_else(|| std::io::Error::other("Child stderr unavailable"))?;
    std::thread::scope(|scope| {
        let writer = scope.spawn(move || -> std::io::Result<()> {
            if let (Some(mut stdin), Some(input)) = (stdin, input) { stdin.write_all(input)?; }
            Ok(())
        });
        let reader = scope.spawn(move || -> std::io::Result<Vec<u8>> {
            let mut output = Vec::new();
            let mut buffer = [0u8; 4096];
            loop {
                let count = stderr.read(&mut buffer)?;
                if count == 0 { break; }
                // Keep the tail, while always draining the pipe to avoid deadlock.
                let excess = output.len().saturating_add(count).saturating_sub(MAX_DIAGNOSTIC_BYTES);
                if excess > 0 { output.drain(..excess); }
                output.extend_from_slice(&buffer[..count]);
            }
            Ok(output)
        });
        let start = Instant::now();
        let status = loop {
            match child.try_wait() {
                Ok(Some(status)) => break Ok(status),
                Ok(None) if start.elapsed() < deadline => std::thread::sleep(Duration::from_millis(10)),
                Ok(None) => {
                    let _ = child.kill(); let _ = child.wait();
                    break Err(std::io::Error::new(std::io::ErrorKind::TimedOut, "Audio encoder exceeded its time limit; recovery files were retained"));
                }
                Err(error) => { let _ = child.kill(); let _ = child.wait(); break Err(error); }
            }
        };
        let written = writer.join().map_err(|_| std::io::Error::other("Encoder input worker panicked"))?;
        let diagnostics = reader.join().map_err(|_| std::io::Error::other("Encoder diagnostics worker panicked"))??;
        let status = status?;
        // Preserve the process diagnostic on a nonzero exit, even on broken pipe.
        if status.success() { written?; }
        Ok(ProcessOutput { status, stderr: diagnostics })
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    #[cfg(unix)]
    #[test]
    fn drains_input_and_large_stderr_without_deadlock() {
        let mut command = Command::new("sh");
        command.args(["-c", "head -c 200000 /dev/zero >&2; cat >/dev/null"]);
        let output = run(&mut command, Some(&vec![0; 1_000_000]), Duration::from_secs(5)).unwrap();
        assert!(output.status.success());
        assert_eq!(output.stderr.len(), MAX_DIAGNOSTIC_BYTES);
    }
    #[cfg(unix)]
    #[test]
    fn deadline_kills_and_reaps_a_stalled_encoder() {
        let mut command = Command::new("sh");
        command.args(["-c", "exec sleep 30"]);
        let start = Instant::now();
        let error = run(&mut command, Some(&vec![0; 1_000_000]), Duration::from_millis(60)).err().unwrap();
        assert_eq!(error.kind(), std::io::ErrorKind::TimedOut);
        assert!(start.elapsed() < Duration::from_secs(5));
    }
    #[test]
    fn spawn_failure_returns_an_error_not_a_panic() {
        assert!(run(&mut Command::new("nonexistent-clawscribe-encoder"), None, Duration::from_secs(1)).is_err());
    }
}

//! Bounded Unicode-safe source excerpts. The limit is characters, NOT tokens.
//! Keep the beginning/end without making a second full-transcript allocation.
use std::collections::VecDeque;

pub struct ContextExcerpt {
    pub text: String,
    pub truncated: bool,
    pub source_chars: usize,
}

pub struct ContextBuilder {
    head: String,
    tail: VecDeque<char>,
    head_limit: usize,
    tail_limit: usize,
    source_chars: usize,
}

impl ContextBuilder {
    pub fn new(limit: usize) -> Self {
        let head_limit = limit / 3 * 2;
        Self { head: String::new(), tail: VecDeque::new(), head_limit,
            tail_limit: limit - head_limit, source_chars: 0 }
    }
    pub fn push_str(&mut self, source: &str) {
        for character in source.chars() {
            if self.source_chars < self.head_limit {
                self.head.push(character);
            } else if self.tail_limit > 0 {
                if self.tail.len() == self.tail_limit { self.tail.pop_front(); }
                self.tail.push_back(character);
            }
            self.source_chars = self.source_chars.saturating_add(1);
        }
    }
    pub fn finish(self) -> ContextExcerpt {
        let truncated = self.source_chars > self.head_limit + self.tail_limit;
        let mut text = self.head;
        if truncated { text.push_str("\n[Middle of source omitted for length]\n"); }
        text.extend(self.tail);
        ContextExcerpt { text, truncated, source_chars: self.source_chars }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn short_unicode_is_not_duplicated_or_marked_truncated() {
        let mut builder = ContextBuilder::new(12);
        builder.push_str("😀日本語äöü");
        let result = builder.finish();
        assert_eq!(result.text, "😀日本語äöü");
        assert_eq!(result.source_chars, 7);
        assert!(!result.truncated);
    }
    #[test]
    fn exactly_at_limit_retains_every_character() {
        for limit in 0..30 {
            let source = "😀".repeat(limit);
            let mut builder = ContextBuilder::new(limit);
            builder.push_str(&source);
            let result = builder.finish();
            assert!(!result.truncated);
            assert_eq!(result.text, source);
        }
    }
    #[test]
    fn long_source_is_bounded_and_has_explicit_coverage() {
        let mut builder = ContextBuilder::new(9);
        builder.push_str("Opening-");
        for _ in 0..10_000 { builder.push_str("中"); }
        builder.push_str("END");
        let result = builder.finish();
        assert!(result.truncated);
        assert!(result.text.starts_with("Openin"));
        assert!(result.text.ends_with("END"));
        assert_eq!(result.source_chars, 10_011);
        assert_eq!(result.text.chars().count(), 9 + "\n[Middle of source omitted for length]\n".len());
    }
    #[test]
    fn streaming_and_single_input_have_identical_results() {
        let parts = ["Er kommt. ", "日本語 😀", "Final decision."];
        let mut streamed = ContextBuilder::new(15);
        for part in parts { streamed.push_str(part); }
        let mut whole = ContextBuilder::new(15);
        whole.push_str(&parts.concat());
        assert_eq!(streamed.finish().text, whole.finish().text);
    }
}

//! Only one send/clear mutation per meeting. The guard covers provider work,
//! but try_lock returns immediately rather than making another UI action wait.
use once_cell::sync::Lazy;
use std::collections::HashMap;
use std::sync::{Arc, Mutex, Weak};
use tokio::sync::{Mutex as AsyncMutex, OwnedMutexGuard};

static ACTIVE: Lazy<Mutex<HashMap<String, Weak<AsyncMutex<()>>>>> = Lazy::new(|| Mutex::new(HashMap::new()));

pub fn begin(meeting_id: &str) -> Result<OwnedMutexGuard<()>, String> {
    let lock = {
        let mut active = ACTIVE.lock().map_err(|_| "Chat operation registry unavailable")?;
        // Expired meetings do not accumulate in the registry across long sessions.
        active.retain(|_, lock| lock.strong_count() > 0);
        match active.get(meeting_id).and_then(Weak::upgrade) {
            Some(lock) => lock,
            None => {
                let lock = Arc::new(AsyncMutex::new(()));
                active.insert(meeting_id.to_string(), Arc::downgrade(&lock));
                lock
            }
        }
    };
    lock.try_lock_owned().map_err(|_| "An answer or clear operation is already running for this meeting. Please wait for it to finish.".to_string())
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn same_meeting_cannot_send_or_clear_concurrently() {
        let guard = begin("guard-same").unwrap();
        assert!(begin("guard-same").is_err());
        drop(guard);
        assert!(begin("guard-same").is_ok());
    }
    #[test]
    fn different_meetings_do_not_block_each_other() {
        let _first = begin("guard-first").unwrap();
        let _second = begin("guard-second").unwrap();
    }
}
